const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-122.107805, 39.493523]);
  const radius = 10 * 1609.34; // 10 miles to meters
  const geom = point.buffer(radius);

  const date1Start = '2021-09-01';
  const date1End = '2021-09-07';
  const date2Start = '2022-09-13';
  const date2End = '2022-09-19';

  // 2. Cloud masking function
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. Calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 4. Data Acquisition for 2021
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(geom)
    .filterDate(date1Start, date1End)
    .map(maskS2clouds)
    .map(addNDVI);

  const size1 = col1.size().getInfo();
  console.log(`2021 Images found: ${size1}`);

  if (size1 === 0) {
    console.log('No data for Sept 2021.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Data Acquisition for 2022
  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(geom)
    .filterDate(date2Start, date2End)
    .map(maskS2clouds)
    .map(addNDVI);

  const size2 = col2.size().getInfo();
  console.log(`2022 Images found: ${size2}`);

  if (size2 === 0) {
    console.log('No data for Sept 2022.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Calculate mean NDVI for each period
  const ndvi2021 = col1.select('NDVI').mean();
  const ndvi2022 = col2.select('NDVI').mean();

  // 7. Check valid pixels for 2021
  const count2021 = ndvi2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count2021 === 0) {
    console.log('No valid pixels for 2021 after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 8. Check valid pixels for 2022
  const count2022 = ndvi2022.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count2022 === 0) {
    console.log('No valid pixels for 2022 after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 9. Calculate mean NDVI values
  const val2021 = ndvi2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geom,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const val2022 = ndvi2022.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geom,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 10. Validation & Final Answer
  console.log(`2021 NDVI: ${val2021.toFixed(4)}, Valid Pixels: ${count2021}`);
  console.log(`2022 NDVI: ${val2022.toFixed(4)}, Valid Pixels: ${count2022}`);

  if (val2021 === null || val2022 === null || isNaN(val2021) || isNaN(val2022)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (val2021 < -1 || val2021 > 1 || val2022 < -1 || val2022 > 1) {
    console.log('Invalid NDVI range detected.');
    console.log('<answer>C3</answer>');
    return;
  }

  const change = val2022 - val2021;
  console.log(`NDVI Change: ${change.toFixed(4)}`);

  if (val2022 < val2021) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
